import React,{useMemo,useState,useEffect}from'react';
import EnglishTimedQuiz from './EnglishTimedQuiz.jsx';
import './EnglishParagraphEssayTopic.css';

const LESSONS=[
{n:'01',group:'FOUNDATION',title:'What is a paragraph?',simple:'A paragraph is a focused group of sentences developing one central idea. In an exam answer, every sentence should contribute to the same topic.',meaning:'Keep one central idea in control from opening to closing.',structure:'topic → topic sentence → supporting sentences → closing',examples:['Topic: Importance of Reading','Main idea: Regular reading improves vocabulary, knowledge and concentration.','Support: Give reasons, examples and relevant effects.'],clue:'Every sentence should answer: “How does this help develop the central idea?”'},
{n:'02',group:'FOUNDATION',title:'What is an essay?',simple:'An essay develops a broader topic through an introduction, logically organised body paragraphs and a purposeful conclusion.',meaning:'An essay needs larger-scale organisation than a single paragraph.',structure:'introduction → body paragraphs → conclusion',examples:['Introduction: establish the issue and direction.','Body: develop separate but connected points.','Conclusion: synthesise and close the discussion.'],clue:'Do not treat an essay as several unrelated paragraphs placed together.'},
{n:'03',group:'PLANNING',title:'Topic + controlling idea',simple:'The topic tells what you are writing about; the controlling idea tells the specific point you will develop.',meaning:'A strong controlling idea narrows a broad topic into a manageable writing direction.',structure:'topic + specific claim = controlling direction',examples:['Topic: Trees in our town','Controlling idea: Trees improve health and the local environment.','Use the controlling idea to decide which details belong.'],clue:'When the topic feels too broad, add a clear claim or angle before drafting.'},
{n:'04',group:'STRUCTURE',title:'Topic sentence',simple:'A strong paragraph commonly begins with a topic sentence that signals its main idea. Avoid opening with an unrelated fact or a conclusion before the reader knows the subject.',meaning:'The topic sentence gives the paragraph its central direction.',structure:'topic sentence → explanation → evidence/example → closure',examples:['Weak: “There are many things in the world.”','Better: “Regular exercise improves both physical and mental well-being.”','Then support the exact claim.'],clue:'Topic-sentence test: can the rest of the paragraph directly explain, illustrate or justify the first sentence?'},
{n:'05',group:'DEVELOPMENT',title:'Supporting sentences',simple:'Support the main idea with explanations, reasons, facts, examples, comparisons or relevant details. Strong support answers questions such as how, why, when, where or with what effect.',meaning:'Support turns a claim into developed writing.',structure:'claim → explanation → example/fact → effect',examples:['Claim: Reading improves vocabulary.','Explanation: Frequent exposure introduces new words in context.','Example: Students meet those words repeatedly while reading.'],clue:'Do not count repetition as support; each supporting sentence should add something useful.'},
{n:'06',group:'CONTROL',title:'Unity',simple:'Unity means every sentence serves the same central idea. Remove attractive but unrelated facts instead of forcing them into the paragraph.',meaning:'Unity protects focus.',structure:'one controlling idea → only relevant details',examples:['Water-saving paragraph: turn off taps, repair leaks, collect rainwater.','Irrelevant: a sentence about your favourite sport.'],clue:'Ask: “If I delete this sentence, do I lose an important part of the same idea?”'},
{n:'07',group:'CONTROL',title:'Coherence',simple:'Coherence means ideas connect in a logical sequence. Use clear sentence order, pronouns and suitable connectors so the reader can follow the thought without guessing.',meaning:'Coherence is the reader’s ability to follow your thinking easily.',structure:'idea A → logical bridge → idea B → logical bridge → conclusion',examples:['First identify the problem.','Next explain why it matters.','Finally propose practical solutions.'],clue:'A sequence can be logical even without many connectors; connectors should clarify, not decorate.'},
{n:'08',group:'LANGUAGE',title:'Cohesive devices',simple:'Use connectors according to meaning: first/next for sequence, because/since for reason, however for contrast, therefore/thus for result, for example for illustration and finally/in conclusion for closure.',meaning:'Cohesive devices show relationships between ideas.',structure:'sequence | reason | contrast | result | example | closure',examples:['First, collect the information.','The road was flooded; therefore, buses were delayed.','The plan is useful; however, it is expensive.'],clue:'Connector audit: replace a connector with its plain meaning. If the relationship changes, choose a different connector.'},
{n:'09',group:'DEVELOPMENT',title:'Paragraph development patterns',simple:'Common patterns include description, narration, cause–effect, problem–solution, comparison and argument. Choose the pattern that fits the task rather than using the same structure every time.',meaning:'Development pattern should match the writer’s purpose.',structure:'description | narration | cause–effect | problem–solution | comparison | argument',examples:['Description: overall scene → vivid details.','Narration: setting → events → outcome.','Cause–effect: cause → mechanism → effect.'],clue:'Read the command word in the prompt before choosing your structure.'},
{n:'10',group:'ESSAY',title:'Writing an introduction',simple:'An effective essay introduction establishes the topic, gives context when needed and states the direction or central position. Do not waste the opening on dictionary definitions unless they help the task.',meaning:'The introduction prepares the reader for the exact discussion that follows.',structure:'context → topic → direction/position',examples:['Value of Time: explain why time matters, then state the main direction.','Argument essay: make your position identifiable.'],clue:'Avoid announcing the essay mechanically with lines such as “I am going to write an essay…” unless required.'},
{n:'11',group:'ESSAY',title:'Body paragraph control',simple:'One body paragraph should usually have one main function. Begin with its controlling sentence, develop it with evidence or explanation and connect it back to the essay topic.',meaning:'Each body paragraph should perform a clear job.',structure:'controlling sentence → development → support → link',examples:['Paragraph 1: benefit of reading.','Paragraph 2: effect on concentration.','Paragraph 3: practical reading habits.'],clue:'A good body paragraph can be summarised in one sentence before you draft it.'},
{n:'12',group:'SUPPORT',title:'Examples and evidence',simple:'Examples should clarify the point, not replace reasoning. Prefer specific, relevant illustrations over invented statistics or exaggerated claims.',meaning:'Evidence is valuable when it is relevant, credible and connected to the point.',structure:'point → evidence/example → explanation',examples:['Use a relevant real-life example.','Explain why the example supports the point.','Avoid pretending to know exact percentages you cannot support.'],clue:'Precision without evidence can weaken credibility rather than strengthen it.'},
{n:'13',group:'ARGUMENT',title:'Argument writing',simple:'For an opinion or argument, state a clear position, give reasons, support those reasons and address an important counterpoint when appropriate. Keep the tone respectful and evidence-focused.',meaning:'A strong argument is reasoned, not merely emotional.',structure:'position → reason → support → counterpoint → response → conclusion',examples:['Position: a balanced homework policy is better.','Reason: excessive weekend work can reduce rest and family time.','Response: limited purposeful practice can still support learning.'],clue:'Address the strongest relevant counterpoint rather than an easy version of the opposing view.'},
{n:'14',group:'CAUSE–EFFECT',title:'Cause and effect',simple:'Distinguish cause from effect. Useful signals include because, due to, since and as a result. Do not assume that two events occurring together automatically prove causation.',meaning:'Cause explains why something happens; effect is what happens as a result.',structure:'cause → mechanism/explanation → effect',examples:['Heavy rain caused water to collect on the road, slowing traffic.','As a result of flooding, buses were delayed.'],clue:'Sequence alone does not prove cause. State the relationship clearly when it is justified.'},
{n:'15',group:'PROBLEM–SOLUTION',title:'Problem–solution writing',simple:'State the problem clearly, explain why it matters, propose practical solutions and show how those solutions address the causes or effects.',meaning:'A solution must respond directly to the stated problem.',structure:'problem → impact/cause → solution → how it helps',examples:['Problem: plastic waste.','Solution: refill stations and reusable bottles.','Link: both reduce dependence on single-use plastic.'],clue:'Do not jump to solutions before defining the actual problem.'},
{n:'16',group:'CONCLUSION',title:'Conclusion writing',simple:'A conclusion should synthesise the developed idea and provide closure. It may restate the central position in fresh words, summarise the main insight or end with a relevant implication.',meaning:'A conclusion closes the argument without opening a brand-new major discussion.',structure:'synthesis → final implication/position → closure',examples:['Restate the central idea in fresh words.','Summarise the strongest insight.','End with a relevant responsibility or implication.'],clue:'A major new argument belongs in the body, not as an unexpected final paragraph.'},
{n:'17',group:'EDITING',title:'Language and editing',simple:'Prefer precise vocabulary, complete sentences and consistent tense. Check articles, subject–verb agreement, punctuation, spelling, repetition and sentence boundaries.',meaning:'Good ideas still need accurate expression.',structure:'content check → organisation check → grammar → spelling → punctuation',examples:['Remove repeated ideas.','Fix comma splices and incomplete sentences.','Check articles, agreement and tense consistency.'],clue:'Edit for meaning first, then sentence-level correctness.'},
{n:'18',group:'EXAM CONTROL',title:'Length, layout and exam audit',simple:'Follow the task’s expected length. Use readable paragraphs, a clear title when requested and a logical beginning–middle–end structure. Final audit: task → purpose → unity → coherence → support → grammar → spelling → punctuation → conclusion.',meaning:'Exam writing is controlled writing: complete, relevant and accurate within the required format.',structure:'task → plan → draft → revise → final audit',examples:['Check word range.','Check title/paragraph format if required.','Read the prompt once more before submission.'],clue:'Fancy vocabulary matters less than task fulfilment, clarity, relevance and correct language.'}
];

const EXAMPLES=[['TOPIC','Importance of Reading','Use a clear central idea: “Regular reading improves vocabulary, knowledge and concentration.”'],['TOPIC','Cleanliness in School','Narrow the focus: “A clean school creates a healthier and more pleasant learning environment.”'],['OPENING','Trees and Our Future','“Trees are not merely part of the landscape; they are essential to a healthy future.”'],['SUPPORT','Why trees matter','“They provide shade, absorb carbon dioxide and create habitats for living organisms.”'],['CONNECTOR','Cause → result','“The road was flooded; therefore, the buses were delayed.”'],['CONNECTOR','Contrast','“Online learning is convenient; however, it cannot always replace direct classroom interaction.”'],['CONCLUSION','Saving Water','“Therefore, careful use of water is not a small personal habit but a shared responsibility.”'],['ARGUMENT','School Library','“A well-used library supports independent learning because students can explore material beyond the textbook.”'],['PROBLEM–SOLUTION','Plastic waste','“Schools can reduce single-use plastic by providing refill stations and encouraging reusable bottles.”'],['DESCRIPTIVE','A Morning Walk','“The early road was quiet, the air felt fresh and the trees were alive with birdsong.”']];
